import type { AnimationConfigWithData, AnimationItem, LottiePlayer } from 'lottie-web';
import { CuePalette } from './cue-palette';

/**
 * Authored Lottie animations that effects draw as one layer on the overlay. The files live in
 * `public/cue-animations/` and are generated by `tools/cue-animations/generate.mjs`.
 *
 * Nothing here is in the initial bundle: `preloadCueAnimations` fetches the files and then
 * lazy-loads lottie-web's light canvas build (no expressions, no SVG/HTML renderers). Until that
 * has finished — or when it fails, or in environments without a 2D canvas such as jsdom —
 * `drawCueAnimation` draws nothing and returns false, so every effect keeps a canvas-only
 * fallback and never waits for a file.
 *
 * Each animation is rendered by lottie into its own offscreen canvas at the requested frame and
 * then copied onto the overlay, so lottie never touches the overlay's transform. Colors are
 * palette slots: a fill or stroke named `@accent`, `@c0`, `@c1` or `@c2` takes that color of the
 * effect's {@link CuePalette}, one lottie instance per animation and look.
 */

/** Every file in `public/cue-animations/`, without `.json`. */
export const CUE_ANIMATIONS = [
  'impact', 'sigil', 'shatter', 'crack', 'pillar', 'vortex', 'wisp', 'life-gain', 'life-loss', 'badge',
  'doom-cloud', 'skull'
] as const;

export type CueAnimationName = typeof CUE_ANIMATIONS[number];

/** Composition pixels per card unit: a 200 px wide composition is drawn twice the anchor's unit wide. */
export const COMPOSITION_UNIT = 100;

/** Offscreen canvas pixels per composition pixel. */
const RESOLUTION = 2;

/** Where an animation is drawn: its middle, and the size of one card unit on screen. */
export interface CueAnimationAnchor {
  x: number;
  y: number;
  unit: number;
}

/** The parts of a Lottie file this module reads. */
export interface CueAnimationData {
  w: number;
  h: number;
  ip: number;
  op: number;
  layers: unknown[];
}

interface Instance {
  item: AnimationItem;
  canvas: HTMLCanvasElement;
  data: CueAnimationData;
}

let lottie: LottiePlayer | null = null;
let files = new Map<CueAnimationName, CueAnimationData>();
let instances = new Map<string, Instance | null>();
let loading: Promise<boolean> | null = null;

function fetchAnimation(name: CueAnimationName): Promise<CueAnimationData> {
  return fetch(new URL(`cue-animations/${name}.json`, document.baseURI)).then(response => {
    if (!response.ok) throw new Error(`cue animation ${name}: HTTP ${response.status}`);
    return response.json();
  });
}

/**
 * Loads every animation and the lottie library, once; resolves true when they can be drawn.
 * A failure resolves false and leaves effects on their canvas fallbacks; the next call tries again.
 */
export function preloadCueAnimations(load: (name: CueAnimationName) => Promise<CueAnimationData> = fetchAnimation): Promise<boolean> {
  loading ??= (async () => {
    try {
      const loaded = await Promise.all(CUE_ANIMATIONS.map(async name => [name, await load(name)] as const));
      const module = await import('lottie-web/build/player/esm/lottie_light_canvas.min.js');
      files = new Map(loaded);
      lottie = module.default;
      return true;
    } catch {
      loading = null;
      return false;
    }
  })();
  return loading;
}

/** Whether {@link drawCueAnimation} can draw. */
export function cueAnimationsReady(): boolean {
  return lottie !== null;
}

/** Forgets everything loaded, so effects fall back to canvas drawing again. For specs. */
export function resetCueAnimations(): void {
  instances.forEach(instance => instance?.item.destroy());
  lottie = null;
  files = new Map();
  instances = new Map();
  loading = null;
}

/** The slot colors of a look, as Lottie `[r, g, b, a]` in 0..1. */
function slotColors(palette: CuePalette): Record<string, number[]> {
  const [c0, c1, c2 = c1] = palette.colors;
  return { '@accent': lottieColor(palette.accent), '@c0': lottieColor(c0), '@c1': lottieColor(c1), '@c2': lottieColor(c2) };
}

function lottieColor(rgb: string): number[] {
  const [r, g, b] = (rgb.match(/\d+(\.\d+)?/g) ?? ['0', '0', '0']).map(Number);
  return [r / 255, g / 255, b / 255, 1];
}

/**
 * A copy of `data` with every fill and stroke named after a palette slot (`@accent`, `@c0`, `@c1`,
 * `@c2`) set to that color of `palette`. Fixed colors are left alone.
 */
export function recolorAnimation<T>(data: T, palette: CuePalette): T {
  const colors = slotColors(palette);
  const copy = structuredClone(data);
  const visit = (node: unknown): void => {
    if (Array.isArray(node)) {
      node.forEach(visit);
      return;
    }
    if (!node || typeof node !== 'object') return;
    const item = node as Record<string, unknown>;
    const color = typeof item['nm'] === 'string' ? colors[item['nm']] : undefined;
    if ((item['ty'] === 'fl' || item['ty'] === 'st') && color) {
      item['c'] = { a: 0, k: color };
    }
    Object.values(item).forEach(visit);
  };
  visit(copy);
  return copy;
}

function instanceFor(name: CueAnimationName, palette: CuePalette): Instance | null {
  const key = name + '|' + palette.element;
  if (instances.has(key)) return instances.get(key)!;
  const data = files.get(name);
  let instance: Instance | null = null;
  if (lottie && data) {
    const canvas = document.createElement('canvas');
    canvas.width = data.w * RESOLUTION;
    canvas.height = data.h * RESOLUTION;
    const context = canvas.getContext('2d');
    if (context) {
      // No container: lottie renders into the given context instead of adding a canvas to the page.
      const config = {
        renderer: 'canvas', loop: false, autoplay: false, animationData: recolorAnimation(data, palette),
        rendererSettings: { context, clearCanvas: true, dpr: 1, preserveAspectRatio: 'xMidYMid meet' }
      } as AnimationConfigWithData<'canvas'>;
      instance = { item: lottie.loadAnimation(config), canvas, data };
    }
  }
  instances.set(key, instance);
  return instance;
}

/**
 * Draws `name` in `palette`'s colors at `progress` (0..1 over the whole animation), centred on
 * `at` and sized by its unit times `scale`. Respects the context's alpha and transform. Returns
 * false, drawing nothing, when the animations are not loaded.
 */
export function drawCueAnimation(draw: CanvasRenderingContext2D, name: CueAnimationName, palette: CuePalette,
                                 progress: number, at: CueAnimationAnchor, scale = 1): boolean {
  const instance = lottie ? instanceFor(name, palette) : null;
  if (!instance) return false;
  const frames = instance.data.op - instance.data.ip;
  instance.item.goToAndStop(Math.min(1, Math.max(0, progress)) * (frames - 1), true);
  const width = instance.data.w / COMPOSITION_UNIT * at.unit * scale;
  const height = instance.data.h / COMPOSITION_UNIT * at.unit * scale;
  draw.drawImage(instance.canvas, at.x - width / 2, at.y - height / 2, width, height);
  return true;
}
